# ============================================================================
# SAC-NO  PROBE 2 -- ONE NET, A WHOLE SYMMETRY SHEET (parametric operator)
# ----------------------------------------------------------------------------
# Goal: show that a SINGLE similarity-anchored neural operator, trained on a few
# members of a Lie-symmetry orbit, GENERALISES to held-out members it never saw.
# This is the operator-learning claim of SAC-NO: because the solution family is
# generated by a symmetry and the operator reads the INVARIANT (similarity)
# coordinate plus the scalar orbit label, one net covers the entire sheet.
#
# Sheet: the Burgers travelling-wave kink family.  Burgers  u_t + u u_x = nu u_xx
# in the co-moving similarity coordinate  z = x - c t  reduces (c=0 WLOG by the
# Galilean shift) to  nu U'' = U U', whose exact kinks are
#       U(z; k) = -k tanh( k z / (2 nu) ),   k > 0.
# The Burgers SCALING symmetry  X = 2 t d_t + x d_x - u d_u  acts as
#       z -> lambda z,  U -> U/lambda   =>   k -> k/lambda,
# so { U(.;k) } is one SCALING ORBIT ("the sheet"); k is the orbit coordinate.
# Every member is closed-form, so held-out error is exact and honest.
#
# Operator (the standard neural-operator protocol -- train on input/output pairs):
#   N_theta(z, k)  reads the invariant coord z AND the orbit label k, and is fit
#   (supervised, MSE) to the exact U at a handful of TRAIN labels.  We then test
#   on a DISJOINT set of labels -- pure interpolation and one extrapolation.
#   Body: Linear(2,32)-Tanh-Linear(32,32)-Tanh-Linear(32,1) = 1185 params.
#
# CONTRAST (the SAC-NO point): an operator that reads the orbit label is anchored
# to the quotient and the family collapses to a smooth 1-D dependence it learns
# from few samples.  A plain PINN must be RE-SOLVED from scratch for each new k.
# ============================================================================
import torch, time, math

torch.set_default_dtype(torch.float64)
torch.manual_seed(0)

nu = 0.5
Z  = 8.0
def U_exact(z, k):                       # closed-form kink, the oracle for every k
    return -k * torch.tanh(k * z / (2.0 * nu))

# ---- 1185-parameter similarity-anchored operator ----------------------------
net = torch.nn.Sequential(
    torch.nn.Linear(2, 32), torch.nn.Tanh(),
    torch.nn.Linear(32, 32), torch.nn.Tanh(),
    torch.nn.Linear(32, 1))
nparams = sum(p.numel() for p in net.parameters())
def N(z, k):
    return net(torch.cat([z, k], dim=1))

# ---- the training sheet (few members) and a DISJOINT held-out set ------------
K_TRAIN = torch.tensor([0.6, 0.8, 1.0, 1.2, 1.4])     # members the net is fit on
K_TEST  = torch.tensor([0.7, 0.9, 1.1, 1.3])          # held out -- interpolation
K_EXTRA = torch.tensor([1.7, 2.0])                    # held out -- extrapolation

nz = 161
zc = torch.linspace(-Z, Z, nz).reshape(-1, 1)
# supervised training tensors over the TRAIN band only
zz = zc.repeat(len(K_TRAIN), 1)
kk = K_TRAIN.repeat_interleave(nz).reshape(-1, 1)
yy = U_exact(zz, kk)                                  # exact targets at train labels

opt = torch.optim.LBFGS(net.parameters(), max_iter=400, history_size=80,
                        tolerance_grad=1e-14, tolerance_change=1e-16,
                        line_search_fn='strong_wolfe')
def closure():
    opt.zero_grad()
    loss = ((N(zz, kk) - yy) ** 2).mean()
    loss.backward()
    return loss
t0 = time.time(); opt.step(closure); train_s = time.time() - t0
train_mse = ((N(zz, kk) - yy).detach() ** 2).mean().sqrt().item()

# ---- evaluation: rel-L2 vs the exact kink on train / held-out ----------------
def relL2_at(k_val):
    with torch.no_grad():
        zg = torch.linspace(-Z, Z, 801).reshape(-1, 1)
        kg = torch.full_like(zg, k_val)
        up, ue = N(zg, kg), U_exact(zg, k_val)
        return (up - ue).pow(2).mean().sqrt().item() / ue.pow(2).mean().sqrt().item()

print("=" * 70)
print("SAC-NO PROBE 2 -- PARAMETRIC OPERATOR OVER A SYMMETRY SHEET")
print("=" * 70)
print(f"sheet: Burgers kinks U(z;k) = -k tanh(kz/2nu), nu={nu} (a scaling orbit)")
print(f"operator: Linear(2,32)-Tanh-Linear(32,32)-Tanh-Linear(32,1) = {nparams} params")
print(f"supervised on {len(K_TRAIN)} orbit labels k in {list(K_TRAIN.numpy())}")
print(f"train_time = {train_s:.2f}s   train RMSE = {train_mse:.2e}")
print("-" * 70)
tr = [relL2_at(k) for k in K_TRAIN.tolist()]
te = [relL2_at(k) for k in K_TEST.tolist()]
ex = [relL2_at(k) for k in K_EXTRA.tolist()]
print("rel-L2 on TRAINED labels   :", "  ".join(f"k={k:.1f}:{e:.2e}" for k, e in zip(K_TRAIN.tolist(), tr)))
print("rel-L2 on HELD-OUT (interp):", "  ".join(f"k={k:.1f}:{e:.2e}" for k, e in zip(K_TEST.tolist(), te)))
print("rel-L2 on HELD-OUT (extrap):", "  ".join(f"k={k:.1f}:{e:.2e}" for k, e in zip(K_EXTRA.tolist(), ex)))
mean_heldout = sum(te) / len(te)
worst_heldout = max(te)
print("-" * 70)
print(f"held-out (interpolation) rel-L2: mean {mean_heldout:.2e}, worst {worst_heldout:.2e}")
ok = worst_heldout < 1e-2
print(f"VERDICT: one operator generalises across the sheet to held-out members "
      f"(worst interp rel-L2 < 1e-2): {'PASS' if ok else 'FAIL'}")
print("Interpretation: anchoring inputs to the orbit quotient collapses the")
print("symmetry-generated family to a smooth 1-D dependence on the orbit label;")
print("the operator learns it from a handful of members and interpolates the")
print("rest -- whereas a plain PINN must be re-solved from scratch for each k.")
